#!/usr/bin/env python3
"""pharma/poppk_fit — auto-generated run.py (archetype=pharma).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "pharma"
BRAIN = "pharma"
SKILL = "poppk_fit"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'poppk_fit', 'n_compounds': 0, 'admet_csv': '', 'diagnostics': {'brain': 'pharma', 'archetype': 'pharma'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """群体 PK 简化版:用 scipy 对 pooled subject data 拟合 1-compartment 模型。
    (host 无 NONMEM/nlmixr 真 NLME;这里是 naïve pooled fit + per-subject ETA via residual)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    subjects = payload.get("subjects") or []  # [{id, times, concs, dose}]
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_subjects": len(subjects),
                   "tool": "scipy.curve_fit (naive pooled NLME)"}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_compounds": 0, "admet_csv": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not subjects:
        return {"ok": False, "error": "需要 subjects (list of {id, times, concs, dose})",
                "diagnostics": diagnostics}
    script = (
        "import json, sys, numpy as np\n"
        "from scipy.optimize import curve_fit\n"
        f"subs = {subjects!r}\n"
        "def one_cmt(t, dose, cl, v):\n"
        "    ke = cl/v; return dose/v * np.exp(-ke*t)\n"
        "all_t, all_c, all_dose = [], [], []\n"
        "for s in subs:\n"
        "    all_t.extend(s['times']); all_c.extend(s['concs']); all_dose.extend([s['dose']]*len(s['times']))\n"
        "all_t = np.array(all_t); all_c = np.array(all_c); all_dose = np.array(all_dose)\n"
        "def model(_x, cl, v):\n"
        "    return one_cmt(all_t, all_dose, cl, v)\n"
        "try:\n"
        "    popt, pcov = curve_fit(model, all_t, all_c, p0=[10, 30], maxfev=10000)\n"
        "    cl_pop, v_pop = popt\n"
        "    se = np.sqrt(np.diag(pcov))\n"
        "    json.dump({'cl_pop': float(cl_pop), 'v_pop': float(v_pop),\n"
        "               'cl_cv': float(se[0]/cl_pop), 'v_cv': float(se[1]/v_pop),\n"
        "               'n_subjects': len(subs)}, sys.stdout)\n"
        "except Exception as ex:\n"
        "    json.dump({'__err': repr(ex)[:200]}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "poppk fit 失败"),
                "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    if "__err" in parsed:
        return {"ok": False, "error": parsed["__err"], "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "n_compounds": 1, "admet_csv": "",
            **parsed, "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
